// The stuck-party rules against the Rust fixture (generated by
// crates/rules/tests/timeout_ts_fixtures.rs).
import { describe, expect, it } from "vitest";
import fixture from "./__fixtures__/timeouts.json";
import { countdown, dmPhase, revealOverdue, TIMEOUTS_DEFAULT, TIMEOUTS_LOCALNET, turnOverdue, vrfRetryDue } from "./timeouts";

describe("stuck party (deadroll_rules::timeout)", () => {
  it("uses the program's numbers", () => {
    expect(TIMEOUTS_DEFAULT).toEqual(fixture.timeouts);
    expect(TIMEOUTS_LOCALNET).toEqual(fixture.localnet);
  });

  it("matches every case", () => {
    for (const c of fixture.cases) {
      const t = TIMEOUTS_DEFAULT;
      expect(dmPhase({ missingAt: c.missingAt, backAt: c.backAt }, c.now, c.settle, t)).toEqual(c.phase);
      expect(turnOverdue(c.clock, c.now, t)).toBe(c.turnOverdue);
      expect(revealOverdue(c.clock, c.now, t)).toBe(c.revealOverdue);
      expect(vrfRetryDue(c.sent, c.slot, t)).toBe(c.vrfRetryDue);
    }
  });

  it("formats a countdown", () => {
    expect([countdown(3_725), countdown(245), countdown(12), countdown(-5)]).toEqual(["1h 02m", "4m 05s", "12s", "0s"]);
  });
});
